#!/usr/bin/env python3
"""Generate the self-contained player constants; --check never rewrites files."""
import argparse, hashlib, json, re
from pathlib import Path
from urllib.parse import quote
ROOT = Path(__file__).resolve().parents[1]
source = (ROOT/'players/avi-rle.mjs').read_text()
signature = 'export function decodeAVI'
if source.count(signature) != 1 or len(re.findall(r'\bexport\b', source)) != 1:
 raise SystemExit('Expected exactly one decodeAVI export; review the player generator')
decoder = source.replace(signature, 'function decodeAVI', 1)
head = '''<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>ghoulballs video</title><style>html,body{margin:0;background:#080819;color:#fff;height:100%;font:14px monospace}canvas{display:block;width:100%;height:100%;object-fit:contain;image-rendering:pixelated}button{position:fixed;bottom:12px;right:12px;background:#291345;color:#fff;border:1px solid #ea5cb4;padding:8px;cursor:pointer}</style><canvas></canvas><button type=button>Pause</button><script>const encoded="'''
tail = '''";''' + decoder + '''
try{const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),movie=decodeAVI(bytes,{indexed:true}),canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');canvas.width=movie.width;canvas.height=movie.height;let start,paused=false,elapsed=0,lastFrame=-1;const rgba=new Uint8ClampedArray(movie.width*movie.height*4),image=new ImageData(rgba,movie.width,movie.height);const button=document.querySelector('button');button.onclick=()=>{const now=performance.now();if(paused){start=now}else if(start!==undefined){elapsed+=now-start}paused=!paused;button.textContent=paused?'Play':'Pause'};function tick(t){if(start===undefined)start=t;const time=elapsed+(paused?0:t-start),frame=Math.floor(time*movie.fps/1000)%movie.frames.length;if(frame!==lastFrame){const indices=movie.frames[frame],w=movie.width,h=movie.height;for(let y=0;y<h;y++)for(let x=0;x<w;x++)rgba.set(movie.palette[indices[(h-1-y)*w+x]],(y*w+x)*4);ctx.putImageData(image,0,0);lastFrame=frame;}window.__videoFrame=frame;window.__videoLoops=Math.floor(time*movie.fps/1000/movie.frames.length);requestAnimationFrame(tick)}requestAnimationFrame(tick)}catch(e){document.body.textContent='Unable to play this video: '+e.message}
</script>'''
# Keep every double quote and script delimiter outside JSON as percent-encoded bytes.
constants = '// SPDX-License-Identifier: MIT\npragma solidity ^0.8.30;\n\n// GENERATED by scripts/build_video_player.py; source SHA256 '+hashlib.sha256(source.encode()).hexdigest()+'\nlibrary AviPlayer {\n'
for name, text in [('HEAD',head),('TAIL',tail)]:
 constants += '    string internal constant '+name+' =\n        '+json.dumps(quote(text,safe='-._~'))+';\n'
constants+='}\n'
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
path=ROOT/'src/AviPlayer.sol'
if args.check:
 if not path.exists() or path.read_text()!=constants:
  raise SystemExit('Player constants are stale; regenerate them')
else:path.write_text(constants)
